54:     dirs.forEach(([dr,dc])=>{let r=piece.r+dr,c=piece.c+dc;while(inBounds(r,c)){const o=at(r,c);if(!o)moves.push({r,c});else{if(o.side!==piece.side)moves.push({r,c,capture:true});break;}r+=dr;c+=dc;}});
55:   }
56:   return moves;
57: }
58: function render() {
59:   boardEl.innerHTML='';
60:   const moveMap=new Map(legalMoves.map(m=>[`${m.r},${m.c}`,m]));
61:   for(let r=0;r<6;r++)for(let c=0;c<6;c++){
62:     const cell=document.createElement('button');cell.type='button';cell.className=`cell ${(r+c)%2?'dark':'light'}`;cell.setAttribute('role','gridcell');cell.setAttribute('aria-label',`${String.fromCharCode(97+c)}${6-r}`);
63:     if(selected?.r===r&&selected?.c===c)cell.classList.add('selected');
64:     if(lastMove?.some(pos=>pos.r===r&&pos.c===c))cell.classList.add('last-move');
65:     const possible=moveMap.get(`${r},${c}`);if(possible)cell.classList.add(possible.capture?'capture-legal':'legal');
66:     const p=at(r,c);if(p){const glyph=document.createElement('span');glyph.className=`piece ${p.side} ${p.type}`;glyph.textContent=symbols[p.side][p.type];cell.appendChild(glyph);cell.setAttribute('aria-label',`${names[p.type]} ${p.side==='player'?'aliado':'enemigo'} en ${String.fromCharCode(97+c)}${6-r}`);}
67:     cell.addEventListener('click',()=>onCell(r,c));boardEl.appendChild(cell);
68:   }
69:   updateHUD();
70: }
71: function onCell(r,c) {
72:   if(turnBusy||gameFinished||overlay.classList.contains('hidden')===false)return;
73:   const p=at(r,c), move=legalMoves.find(m=>m.r===r&&m.c===c);
74:   if(selected&&move){performPlayerMove(selected,move);return;}
75:   if(p?.side==='player'){
76:     selected={r,c};legalMoves=movesFor(p);document.getElementById('boardHint').textContent=legalMoves.length?'Elige una casilla iluminada':'Esta pieza no tiene jugadas';render();return;
77:   }
78:   selected=null;legalMoves=[];document.getElementById('boardHint').textContent='Elige una pieza para ver sus jugadas';render();
79: }
80: function performPlayerMove(from,to) {
81:   const piece=at(from.r,from.c);if(!piece)return;
82:   const target=at(to.r,to.c);let capturedName='';
83:   if(target){capturedName=`${names[target.type]} rival`;board=board.filter(p=>p!==target);roomCaptures++;captures++;chips+=1+(mods.has('bounty')?1:0);}
84:   piece.r=to.r;piece.c=to.c;lastMove=[{r:from.r,c:from.c},{r:to.r,c:to.c}];
85:   const notation=`${names[piece.type]} ${String.fromCharCode(97+from.c)}${6-from.r} → ${String.fromCharCode(97+to.c)}${6-to.r}`;
86:   addLog(capturedName?`${notation}. <em>Captura ${capturedName}</em> · +${1+(mods.has('bounty')?1:0)} ficha${mods.has('bounty')?'s':''}.`:notation);
87:   selected=null;legalMoves=[];turnBusy=true;document.getElementById('boardHint').textContent='El crupier piensa...';render();
88:   if(!board.some(p=>p.side==='enemy')){turnBusy=false;winRoom();return;}
89:   const skip=mods.has('free')&&!freeUsed;
90:   if(skip){freeUsed=true;addLog('Jugada gratis: el crupier pierde su respuesta.');turnBusy=false;document.getElementById('boardHint').textContent='Elige tu siguiente pieza';render();return;}
91:   window.setTimeout(enemyTurn,350);
92: }
93: function enemyTurn() {
94:   if(gameFinished)return;
95:   const enemies=board.filter(p=>p.side==='enemy'), options=[];
96:   enemies.forEach(p=>movesFor(p).forEach(m=>options.push({piece:p,move:m})));
97:   if(!options.length){addLog('El crupier no encuentra una jugada.');turnBusy=false;render();return;}
98:   const allies=board.filter(p=>p.side==='player');
99:   options.forEach(o=>{
100:     const target=at(o.move.r,o.move.c);
101:     if(target){o.score=100+value[target.type]*5+(target.type==='king'?100:0);}
102:     else {const nearest=Math.min(...allies.map(a=>Math.abs(a.r-o.move.r)+Math.abs(a.c-o.move.c)));o.score=4-nearest*.35+Math.random()*1.5+(o.piece.type==='pawn'?Math.random()*.4:0);}
103:   });
104:   options.sort((a,b)=>b.score-a.score);
105:   const bestScore=options[0].score, pool=options.filter(o=>o.score>=bestScore-1.6);
106:   const choice=pool[Math.floor(Math.random()*pool.length)], {piece,move}=choice;
107:   const target=at(move.r,move.c);
108:   if(target){
109:     board=board.filter(p=>p!==target);addLog(`El crupier captura tu ${names[target.type].toLowerCase()} en ${String.fromCharCode(97+move.c)}${6-move.r}.`);
110:     if(target.type==='king'){piece.r=move.r;piece.c=move.c;turnBusy=false;render();loseRun();return;}
111:   } else addLog(`El crupier mueve ${names[piece.type].toLowerCase()} a ${String.fromCharCode(97+move.c)}${6-move.r}.`);
112:   const from={r:piece.r,c:piece.c};piece.r=move.r;piece.c=move.c;lastMove=[from,{r:move.r,c:move.c}];turnBusy=false;selected=null;legalMoves=[];document.getElementById('boardHint').textContent='Elige una pieza para ver sus jugadas';render();
113: }
114: function updateHUD() {
115:   const enemies=board.filter(p=>p.side==='enemy'), allies=board.filter(p=>p.side==='player');
116:   document.getElementById('roomLabel').innerHTML=`${String(room+1).padStart(2,'0')} <small>/ 03</small>`;
117:   document.getElementById('chipCount').textContent=String(chips).padStart(2,'0');
118:   document.getElementById('streakLabel').innerHTML=`${streak} <small>victorias</small>`;
119:   document.getElementById('roomTitle').textContent=roomData[room].title;
120:   document.getElementById('roomType').textContent=roomData[room].type;
121:   document.getElementById('roomSubtitle').textContent=roomData[room].subtitle;
122:   document.getElementById('roundNumber').textContent=String(room+1).padStart(2,'0');
123:   document.getElementById('enemyCount').textContent=enemies.length;
124:   document.getElementById('allyCount').innerHTML=`${allies.length} <small>piezas</small>`;
125:   document.getElementById('progressText').textContent=`${roomEnemyStart-enemies.length} / ${roomEnemyStart}`;
126:   document.getElementById('progressFill').style.width=`${((roomEnemyStart-enemies.length)/roomEnemyStart)*100}%`;
127:   document.getElementById('turnIndicator').innerHTML=turnBusy?'<i></i> TURNO DEL CRUPIER':'<i></i> TU TURNO';
128:   document.getElementById('turnIndicator').classList.toggle('enemy-turn',turnBusy);
129:   const order=['king','queen','rook','bishop','knight','pawn'];
130:   document.getElementById('squadList').innerHTML=order.map(type=>{
131:     const units=board.filter(p=>p.side==='player'&&p.type===type);const total=(type==='pawn'&&mods.has('reinforce')&&room>0)?2:1;
132:     return Array.from({length:Math.max(total,units.length)},(_,i)=>{const unit=units[i];return `<div class="squad-unit ${unit?'':'dead'} ${unit&&selected?.r===unit.r&&selected?.c===unit.c?'active':''}"><span class="mini-piece">${symbols.player[type]}</span><span>${names[type]}</span><span class="unit-state">${unit?'EN MESA':'FUERA'}</span></div>`;}).join('');
133:   }).join('');
134:   document.getElementById('battleLog').innerHTML=logLines.slice(-6).map(item=>`<div class="log-entry"><span class="log-time">${item.n}</span><span>${item.text}</span></div>`).join('');
135: }
136: function addLog(text) {logLines.push({n:String(logLines.length+1).padStart(2,'0'),text});if(logLines.length>12)logLines.shift();}
137: function winRoom() {
138:   gameFinished=true;turnBusy=true;streak++;chips+=2+(mods.has('purse')?3:0);render();
139:   if(room===2){
140:     showModal('♛','LA CASA HA CAÍDO','¡Jaque mate al casino!',`<p>Has conquistado las tres mesas y te llevas <strong>${chips} fichas</strong>.</p><p>Capturaste <strong>${captures} piezas</strong> y sobreviviste a la mano final. El rey eres tú.</p>`,[{label:'Volver a jugar',run:()=>resetGame()}]);
141:   } else {
142:     const available=rewardPool.filter(r=>!mods.has(r.id));const shuffled=available.sort(()=>Math.random()-.5).slice(0,3);
143:     const cards=shuffled.map(r=>`<button class="reward-card" data-reward="${r.id}"><span class="reward-icon">${r.icon}</span><h3>${r.title}</h3><p>${r.text}</p><span class="select-label">ELEGIR VENTAJA ↗</span></button>`).join('');
144:     showModal('✦','SALA LIMPIA',`+${2+(mods.has('purse')?3:0)} FICHAS · ELIGE UNA VENTAJA`,`<p>La mesa es tuya. Tu botín sube a <strong>${chips} fichas</strong>.</p><p>Escoge una carta para la siguiente sala:</p><div class="reward-grid">${cards}</div>`,[]);
145:     overlay.querySelectorAll('[data-reward]').forEach(button=>button.addEventListener('click',()=>chooseReward(button.dataset.reward)));
146:   }
147: }
148: function chooseReward(id) {
149:   mods.add(id);const reward=rewardPool.find(r=>r.id===id);streak=room+1;
150:   if(room+1<3){startRoom(room+1);hideModal();addLog(`Ventaja adquirida: ${reward.title}.`);render();}
151: }
152: function loseRun() {
153:   gameFinished=true;selected=null;legalMoves=[];
154:   showModal('♚','FIN DE LA PARTIDA','La casa cobra su deuda',`<p>Tu rey ha caído en la sala <strong>${String(room+1).padStart(2,'0')}</strong>.</p><p>Te llevas <strong>${chips} fichas</strong> y una lección para la próxima mano.</p>`,[{label:'Volver a intentarlo',run:()=>resetGame()}]);
155: }
156: function showModal(icon,kicker,title,body,actions) {
157:   document.getElementById('modalIcon').textContent=icon;document.getElementById('modalKicker').textContent=kicker;document.getElementById('overlayTitle').textContent=title;document.getElementById('modalBody').innerHTML=body;
158:   const actionsEl=document.getElementById('modalActions');actionsEl.innerHTML='';actions.forEach((action,i)=>{const button=document.createElement('button');button.className=`action-button ${i?'secondary':''}`;button.textContent=action.label;button.onclick=action.run;actionsEl.appendChild(button);});
159:   document.getElementById('closeModal').style.display=actions.length?'block':'none';overlay.classList.remove('hidden');
160: }
161: function hideModal(){overlay.classList.add('hidden');}
162: function resetGame(){chips=0;captures=0;roomCaptures=0;streak=0;mods=new Set();logLines=[];hideModal();startRoom(0);}
163: document.getElementById('rulesButton').addEventListener('click',()=>showModal('♘','REGLAS DE LA CASA','Ajedrez. Apuesta. Sobrevive.','<p><strong>1.</strong> Selecciona una pieza blanca y luego una casilla iluminada para mover.</p><p><strong>2.</strong> Cada movimiento permite una respuesta del crupier. Captura sus piezas y protege a tu rey.</p><p><strong>3.</strong> Limpia las tres salas. Tras cada victoria, elige una ventaja permanente.</p><p><strong>Movimientos:</strong> las piezas se mueven como en ajedrez; los peones avanzan hacia arriba y capturan en diagonal. No hay jaque ni enroque.</p>',[{label:'A jugar',run:hideModal}]));
164: document.getElementById('closeModal').addEventListener('click',hideModal);
165: document.getElementById('restartButton').addEventListener('click',()=>showModal('↻','NUEVA MANO','¿Reiniciar la partida?','<p>Tu progreso, ventajas y fichas se perderán. ¿Quieres barajar de nuevo?</p>',[{label:'Seguir jugando',run:hideModal},{label:'Reiniciar',run:resetGame}]));
166: document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!gameFinished)hideModal();});
167: startRoom(0);

*{box-sizing:border-box}
 :root{--ink:#111a17;--felt:#14231d;--felt-2:#1a2c25;--gold:#d8b66d;--gold-hi:#f1d99a;--cream:#f1ecdf;--muted:#8d9b8e;--red:#c95f53;--green:#73b488;--line:rgba(222,198,139,.16);--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',Arial,sans-serif;--mono:'DM Mono',monospace}
 html{background:#0d1512}
body{margin:0;color:var(--cream);font-family:var(--sans);min-height:100vh;background:radial-gradient(ellipse at 42% 34%,#1d3028 0,#111d18 48%,#0d1512 100%);background-attachment:fixed}
.app-shell{width:min(1360px,100%);margin:0 auto;padding:0 40px}
.topbar{height:88px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}
.brand-mark{width:42px;height:42px;border:1px solid rgba(216,182,109,.42);background:linear-gradient(145deg,#28392e,#17231d);border-radius:50%;display:grid;place-items:center;color:var(--gold-hi);font-size:25px;box-shadow:inset 0 0 14px #cba75a16}
.brand-copy{display:grid;gap:2px}
.brand-copy strong{font:700 17px var(--serif);letter-spacing:1.9px}
.brand-copy strong i{font-style:normal;color:var(--gold)}
.brand-copy small{color:#819084;font:9px var(--mono);letter-spacing:2px}
.run-stats{display:flex;gap:36px;margin-left:auto;margin-right:28px}
.stat{display:grid;gap:4px;min-width:72px}
.stat-label{font:9px var(--mono);letter-spacing:1.6px;color:#819084}
.stat strong{font:600 16px var(--mono);color:#e8dfc7}
.stat strong small{font-size:10px;color:#7e8d80;font-weight:400}
.chip-icon{color:var(--gold);font-size:14px;margin-right:5px}
.icon-button{width:30px;height:30px;border-radius:50%;border:1px solid #536054;background:transparent;color:#c6c7b9;font:500 14px var(--serif);cursor:pointer;transition:.2s}
.icon-button:hover{border-color:var(--gold);color:var(--gold-hi)}
.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 318px;gap:38px;padding:35px 0 19px}
.table-area{min-width:0}
.table-heading{height:91px;display:flex;align-items:flex-start;justify-content:space-between}
.eyebrow,.card-label{font:9px var(--mono);letter-spacing:1.45px;color:#a1ac9c}
.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#79b88a;box-shadow:0 0 8px #79b88a;margin:0 6px 1px 0}
.heading-dash{padding:0 7px;color:#57645a}
.table-heading h1{font:700 28px var(--serif);letter-spacing:.1px;margin:8px 0 3px;color:#f0e9d8}
.table-heading p{margin:0;font-size:12px;color:#95a094}
.round-pill{display:flex;align-items:center;gap:9px;border:1px solid var(--line);border-radius:7px;padding:8px 12px;margin-top:8px;background:#17241e}
.round-sigil{color:var(--gold);font-size:19px}
.round-pill span:last-child{display:grid;gap:1px}
.round-pill small{font:8px var(--mono);letter-spacing:1px;color:#899588}
.round-pill b{font:500 13px var(--mono);color:var(--gold-hi)}
.board-frame{max-width:740px;margin:0 auto;padding:15px 20px 11px;background:linear-gradient(135deg,#1d2b24,#17231e 70%);border:1px solid rgba(215,187,123,.2);border-radius:9px;box-shadow:0 18px 50px #0005,inset 0 1px #ffffff08}
.board-topline{display:flex;align-items:center;justify-content:space-between;color:#9da897;font:9px var(--mono);letter-spacing:1.15px;height:20px;margin-bottom:12px}
.board-topline>span:first-child{color:#b4bdad}
.turn-indicator{color:#94c49d;font-size:8px;display:flex;align-items:center;gap:6px}
.turn-indicator i{width:5px;height:5px;background:#83c48e;border-radius:50%;box-shadow:0 0 7px #83c48e}
.board-wrap{width:min(100%,610px);margin:0 auto;position:relative;padding-left:22px;padding-bottom:20px}
.board{width:100%;aspect-ratio:1;display:grid;grid-template-columns:repeat(6,1fr);grid-template-rows:repeat(6,1fr);border:5px solid #8e7547;border-radius:3px;box-shadow:0 7px 15px #0005,0 0 0 1px #d4b87b55;overflow:hidden;position:relative;background:#b9a875}
.cell{display:grid;place-items:center;position:relative;cursor:pointer;user-select:none;transition:filter .14s,transform .12s}
.cell.light{background:#d7c89e}
.cell.dark{background:#77886d}
.cell:hover{filter:brightness(1.12)}
.cell.selected{z-index:2;box-shadow:inset 0 0 0 4px #f4d276,inset 0 0 22px #ffdf7380}
.cell.last-move{box-shadow:inset 0 0 0 100px #f3d16b32}
.cell.legal:after{content:'';position:absolute;width:24%;height:24%;border-radius:50%;background:#1b614b9c;box-shadow:0 0 0 2px #f0dfaa75;z-index:1}
.cell.capture-legal:after{width:80%;height:80%;background:transparent;border:4px solid #ce684e;box-shadow:0 0 0 2px #ffddc133}
.piece{width:75%;height:82%;display:grid;place-items:center;position:relative;z-index:2;font-family:'DejaVu Sans',serif;font-size:clamp(34px,5.1vw,62px);line-height:1;transition:transform .15s,filter .15s;filter:drop-shadow(0 3px 1px #1118)}
.cell:hover .piece{transform:translateY(-2px)}
.piece.player{color:#f4eedc;text-shadow:0 1px #fff,0 3px 0 #a69b83,0 5px 5px #142018aa}
.piece.enemy{color:#342b25;text-shadow:0 1px #86755e,0 3px 0 #1d1b18,0 5px 5px #1119}
.piece.king.player{color:#f1d793}
.piece.king.enemy{color:#b96650}
.rank-labels{position:absolute;left:2px;top:4px;bottom:24px;display:flex;flex-direction:column;justify-content:space-around;color:#a5a58d;font:9px var(--mono)}
.file-labels{position:absolute;left:23px;right:2px;bottom:0;display:grid;grid-template-columns:repeat(6,1fr);text-align:center;color:#a5a58d;font:9px var(--mono)}
.board-footer{height:23px;display:flex;align-items:end;gap:16px;color:#95a194;font-size:9px}
.board-footer>span{display:flex;align-items:center;gap:5px}
.legend-dot{width:8px;height:8px;border-radius:50%;display:inline-block}
.move-dot{background:#36765c}
.capture-dot{border:2px solid #ce684e}
.board-hint{margin-left:auto;color:#b5aa8b;font-family:var(--mono);font-size:8px;letter-spacing:.25px}
.table-bottomline{max-width:740px;margin:15px auto 0;color:#6d7a6e;font:8px var(--mono);letter-spacing:1.1px}
.table-bottomline>span:first-child,.table-bottomline>span:nth-child(2){color:#9e8051}
.table-id{float:right;color:#58665b}
.side-panel{display:flex;flex-direction:column;gap:13px}
.panel-card{background:linear-gradient(145deg,#1b2a23,#16221c);border:1px solid var(--line);border-radius:7px;padding:14px 15px;box-shadow:0 7px 20px #0002}
.card-label{font-size:8px;letter-spacing:1.3px}
.mini-diamond{font-size:9px;color:#c6a45e}
.objective-card{padding:13px 15px 12px}
.card-label:first-child{display:flex;justify-content:space-between}
.objective-main{display:flex;align-items:center;gap:12px;margin:11px 0 12px}
.target-icon{font-family:'DejaVu Sans',serif;font-size:40px;color:#d9bd7a;line-height:1;text-shadow:0 3px 5px #0008}
.objective-main h2{margin:0 0 4px;font:600 16px var(--serif);color:#f0e8d6}
.objective-main p{margin:0;color:#98a296;font-size:10px;line-height:1.55}
.progress-row{display:flex;align-items:center;gap:10px}
.progress-track{height:4px;background:#303e33;border-radius:5px;flex:1;overflow:hidden}
.progress-track span{height:100%;display:block;background:linear-gradient(90deg,#9c7541,#e3c67d);width:0;transition:width .3s}
.progress-row b{font:9px var(--mono);color:#d1bb81}
.arsenal-card{padding-bottom:10px}
.section-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}
.section-title h2{font:600 16px var(--serif);margin:4px 0 0;color:#e8e1d1}
.piece-count{font:10px var(--mono);color:#d4be80}
.piece-count small{font-size:8px;color:#8f998b}
.squad-list{display:grid;grid-template-columns:1fr 1fr;column-gap:5px}
.squad-unit{height:32px;display:flex;align-items:center;gap:7px;border-top:1px solid #ffffff0a;color:#c9cbbb;font-size:10px}
.squad-unit .mini-piece{width:18px;text-align:center;color:#e9dfc5;font:19px 'DejaVu Sans',serif;filter:drop-shadow(0 2px 1px #000)}
.squad-unit.dead{opacity:.34;text-decoration:line-through}
.unit-state{margin-left:auto;color:#768579;font:8px var(--mono)}
.squad-unit.active{color:var(--gold-hi)}
.squad-unit.active .unit-state{color:var(--gold)}
.log-card{padding-bottom:10px}
.log-mark{font-size:13px;color:#a8864e}
.battle-log{min-height:104px;max-height:104px;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end;gap:7px}
.log-entry{display:flex;gap:8px;align-items:baseline;color:#9aa596;font-size:9px;line-height:1.35;animation:fade-in .25s}
.log-entry:first-child{color:#d6cba9}
.log-entry .log-time{flex:none;color:#718174;font:8px var(--mono)}
.log-entry .log-accent{color:#dfc378}
.side-note{display:flex;align-items:center;gap:11px;padding:3px 5px;color:#8a9789}
.side-note>span{color:#c7a45e;font-size:18px}
.side-note p{font:italic 10px var(--serif);line-height:1.45;margin:0}
.side-note b{font-style:normal;color:#d8c99e}
.footer{border-top:1px solid var(--line);height:44px;display:flex;align-items:center;justify-content:space-between;color:#657367;font:8px var(--mono);letter-spacing:.7px}
.footer>span:first-child{color:#899487}
.footer>span:first-child span{color:#ac925d}
.text-button{background:none;border:0;color:#8f9a8b;font:9px var(--mono);cursor:pointer}
.text-button:hover{color:var(--gold-hi)}
.overlay{position:fixed;inset:0;z-index:10;display:grid;place-items:center;padding:20px;background:#080e0cba;backdrop-filter:blur(5px)}
.overlay.hidden{display:none}
