/* Colorful casino-fantasy polish: softly pixelated edges, bold neon accents and juicy feedback. */
:root{--gold:#ffd34f;--gold-hi:#fff0a1;--cream:#fff7e2;--line:#ffffff20;--felt:#14213a;--felt-2:#1d2c4a}
html{background:#101026}
body{background:radial-gradient(ellipse at 18% 12%,#273469 0,transparent 36%),radial-gradient(ellipse at 83% 22%,#44265d 0,transparent 33%),radial-gradient(ellipse at 50% 90%,#124c55 0,transparent 38%),#101026}
.topbar{border-color:#ffffff20}
.brand-mark{border-radius:8px;border:2px solid #ffdc65;background:linear-gradient(145deg,#fb4f91,#743edd);color:#fff4ab;box-shadow:4px 4px 0 #111026,0 0 24px #ff4f9166;animation:mark-bob 3s ease-in-out infinite}
.brand-copy strong i{color:#ffdc65}
.stat strong{color:#fff3ca}
.game-layout{gap:30px}
.table-heading h1{color:#fff0c4;text-shadow:0 3px 0 #332256}
.eyebrow{color:#b4c6ff}
.live-dot{background:#56f0bd;box-shadow:0 0 10px #56f0bd,0 0 20px #56f0bd77}
.round-pill,.panel-card{background:linear-gradient(140deg,#29345b,#1d2746 76%);border:1px solid #aebeff36;box-shadow:0 8px 0 #0c1027,0 12px 28px #0507196b,inset 0 1px #ffffff18;border-radius:6px}
.round-pill{box-shadow:3px 3px 0 #101026,0 0 18px #8272ff22}
.board-frame{position:relative;background:linear-gradient(135deg,#35406b,#24254a);border:2px solid #8e85e9;border-radius:7px;box-shadow:0 10px 0 #11132f,0 18px 48px #070818aa,0 0 30px #8177ff25,inset 0 1px #ffffff35;transition:filter .2s,transform .2s}
.board{border:5px solid #ffd34f;border-radius:2px;box-shadow:0 6px 0 #8e4b9c,0 0 0 2px #fff3a3,0 0 24px #ffcc4d66;overflow:hidden}
.cell{transition:filter .14s,transform .12s,background-color .2s}
.cell.light{background:#ffe5a4}
.cell.dark{background:#6b76c8}
.cell:hover{filter:brightness(1.16) saturate(1.25)}
.cell.selected{box-shadow:inset 0 0 0 4px #fff04f,inset 0 0 28px #ffb738;animation:select-glow .8s steps(2,end) infinite}
.cell.legal:after{background:#25cf9bba;box-shadow:0 0 0 2px #e4fff5,0 0 14px #28e6b7;animation:legal-pulse 1s ease-in-out infinite alternate}
.cell.capture-legal:after{border-color:#ff5577;box-shadow:0 0 0 2px #ffe4ef,0 0 16px #ff5577;animation:capture-pulse .65s ease-in-out infinite alternate}
.piece{filter:drop-shadow(0 3px 0 #283055) drop-shadow(0 0 7px #ffffff60);transition:transform .18s cubic-bezier(.2,1.8,.4,1),filter .18s}
.cell:hover .piece{transform:translateY(-4px) scale(1.08);filter:drop-shadow(0 5px 0 #283055) drop-shadow(0 0 12px #fff)}
.piece.player{color:#fff7de;text-shadow:0 2px 0 #c99047,0 4px 0 #8561a3,0 0 12px #fff6}
.piece.enemy{color:#382849;text-shadow:0 2px 0 #d46b7c,0 4px 0 #583b83,0 0 10px #ff8ea055}
.piece.king.player{color:#ffe66d;text-shadow:0 2px 0 #da7e40,0 4px 0 #9c4c9f,0 0 16px #ffcf39}
.piece.king.enemy{color:#ff769a;text-shadow:0 2px 0 #a33267,0 4px 0 #481e59,0 0 15px #ff598a}
.turn-indicator{color:#62f0ba}.turn-indicator i{background:#62f0ba;box-shadow:0 0 10px #62f0ba}
.turn-indicator.enemy-turn{color:#ff8ca8}.turn-indicator.enemy-turn i{background:#ff668c;box-shadow:0 0 10px #ff668c;animation:legal-pulse .4s infinite alternate}
.progress-track{background:#121a36}.progress-track span{background:linear-gradient(90deg,#4be5bb,#ffd34f,#ff668f);box-shadow:0 0 12px #ffd34f;transition:width .6s cubic-bezier(.2,1.5,.4,1)}
.progress-row b,.piece-count{color:#ffe16b}
.objective-main h2,.section-title h2{color:#fff0cc}
.target-icon{color:#ff79aa;text-shadow:0 0 14px #ff559977}
.squad-unit.active{background:#ffdf4c13;box-shadow:inset 3px 0 #ffdc52}
.squad-unit.active .mini-piece{color:#ffe36e;filter:drop-shadow(0 0 7px #ffcf4d)}
.log-entry:first-child{color:#b9ffdf}
.reward-card{background:linear-gradient(150deg,#2c3863,#202849);border:1px solid #8d87d477;border-radius:4px;box-shadow:3px 3px 0 #11132d;transition:transform .16s cubic-bezier(.2,1.6,.4,1),box-shadow .16s,filter .16s}
.reward-card:hover{border-color:#ffe26a;box-shadow:0 0 0 2px #ffe26a66,4px 6px 0 #11132d,0 0 22px #ffdf4c44;filter:saturate(1.3)}
.reward-icon{color:#ffe26a;text-shadow:0 0 12px #ffcf4d77}
.action-button{background:linear-gradient(180deg,#ffe66f,#ff9e4c);border:2px solid #fff1a1;box-shadow:0 4px 0 #9d4c50,0 0 18px #ffc84b44;border-radius:3px}
.action-button:active{transform:translateY(3px);box-shadow:0 1px 0 #9d4c50}
.modal-card{background:linear-gradient(145deg,#303761,#201d43);border:2px solid #c1a8ff;border-radius:6px;box-shadow:0 8px 0 #111026,0 25px 80px #000b,0 0 38px #ad6dff37}
.modal-icon{color:#ffe66f;text-shadow:0 0 18px #ffe66f88}
.footer{border-color:#ffffff22}
.fx-particle{position:absolute;z-index:5;left:50%;top:50%;width:7px;height:7px;background:var(--spark);box-shadow:0 0 9px var(--spark);clip-path:polygon(50% 0,62% 38%,100% 50%,62% 62%,50% 100%,38% 62%,0 50%,38% 38%);pointer-events:none;animation:spark-pop 650ms cubic-bezier(.1,.8,.2,1) var(--delay) both}
.fx-capture{animation:frame-capture .55s ease-out}.fx-hit{animation:frame-hit .45s ease-out}.fx-win{animation:frame-win .65s ease-out}
.reward-float{position:absolute;z-index:3;left:50%;top:2px;white-space:nowrap;color:var(--reward-color);font:700 10px var(--mono);text-shadow:0 2px 6px #000;pointer-events:none;animation:reward-rise 1s ease-out both}
.stat-chips{position:relative}
.confetti-bit{position:fixed;z-index:12;top:-16px;left:var(--x);width:9px;height:13px;background:var(--confetti);box-shadow:0 0 9px var(--confetti);pointer-events:none;animation:confetti-fall var(--fall) cubic-bezier(.25,.65,.3,1) var(--delay) both}
@keyframes mark-bob{50%{transform:translateY(-2px) rotate(3deg)}}
@keyframes select-glow{to{box-shadow:inset 0 0 0 4px #fff04f,inset 0 0 30px #ffb738}}
@keyframes legal-pulse{to{transform:scale(1.2);filter:brightness(1.45)}}
@keyframes capture-pulse{to{transform:scale(.92);filter:brightness(1.5)}}
@keyframes spark-pop{0%{opacity:0;transform:translate(-50%,-50%) scale(.2)}20%{opacity:1}100%{opacity:0;transform:translate(calc(-50% + var(--dx)),calc(-50% + var(--dy))) scale(.1)}}
@keyframes reward-rise{0%{opacity:0;transform:translate(-50%,8px) scale(.8)}20%{opacity:1;transform:translate(-50%,0) scale(1.1)}100%{opacity:0;transform:translate(-50%,-28px) scale(1)}}
@keyframes frame-capture{25%{filter:brightness(1.5) saturate(1.5);transform:scale(1.008)}100%{filter:none;transform:none}}
@keyframes frame-hit{15%{transform:translateX(-5px);filter:brightness(1.6)}35%{transform:translateX(5px)}55%{transform:translateX(-3px)}100%{transform:none;filter:none}}
@keyframes frame-win{35%{filter:brightness(1.45) saturate(1.5);box-shadow:0 0 45px #ffe45e99}100%{filter:none}}
@keyframes confetti-fall{0%{opacity:0;transform:translateY(-20px) rotate(0)}12%{opacity:1}100%{opacity:0;transform:translateY(110vh) rotate(var(--spin))}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}

